Regarding the problem, specular light violates the law of conservation of energy; I have traced the problem back to GGX's implementation of the Fresnel function.

<img width="1536" height="1024" alt="Image" src="https://github.com/user-attachments/assets/18fe7e94-8a96-47cb-954c-c9c469c316de" />

<div align="center"> On the left, Burley-GGX; in the center, Godot Standard Lighting; and on the right, Standard Material. </div>


    Roughness: 0.1
    Metallic 1.0 and 0.0
    Specular 1.0


This is my GSL recreation of the default lighting for Forward+ described here:
[servers/rendering/renderer_rd/shaders/scene_forward_lights_inc.glsl](https://github.com/godotengine/godot/blob/78d91947f689ea9eb4049f4d6371c0dfcfa0e62f/servers/rendering/renderer_rd/shaders/scene_forward_lights_inc.glsl#L59)

```glsl
shader_type spatial;

const float INV_PI = 0.318309;

uniform vec3 diffuse_color : source_color = vec3(1.0);
uniform float roughness : hint_range(0.0, 1.0, 0.01) = 1.0;
uniform float metallic : hint_range(0.0, 1.0, 0.01) = 0.0;
uniform float metallic_specular : hint_range(0.0, 1.0, 0.01) = 0.5;

float diffuse_burley(
	in float cNdotL,
	in float cNdotV,
	in float cHdotL,
	in float sigma // Roughness.
)
{
	// https://media.disneyanimation.com/uploads/production/publication_asset/48/asset/s2012_pbs_disney_brdf_notes_v3.pdf 
	float FD90 = 2.0 * sigma * cHdotL * cHdotL - 0.5;

	float fd_L = 1.0 + (FD90) * pow(1.0 - cNdotL, 5.0);
	float fd_V = 1.0 + (FD90) * pow(1.0 - cNdotV, 5.0);

	return  fd_V * fd_L * cNdotL * INV_PI;
}

vec3 specular_schlick_ggx(
	in float cNdotL,
	in float cNdotV,
	in float cHdotN,
	in float cHdotL,
	in vec3 rho, // Diffuse Color.
	in float sigma, // Roughness.
	in float m, // Metallic.
	in float s // Metallic Specular.
)
{
	// https://github.com/godotengine/godot/blob/master/servers/rendering/renderer_rd/shaders/scene_forward_lights_inc.glsl
	float a = sigma * sigma; // Variance.
	float a2 = a * a;

	/* Normal Distribution Function (Trowbridge-Reitz) */
	float D = 1.0 + (a2 - 1.0) * cHdotN * cHdotN;

	D = a2 / (PI * D * D);

	/* Geometric Function (Implicit) */
	float G = 0.5 / mix(2.0 * cNdotL * cNdotV, cNdotL + cNdotV, a);

	/* Fresnel Function (Schlick’s Approximation) */
	float dielectric = 0.16 * s * s;

	vec3 f0 = mix(vec3( dielectric ), rho, vec3( m )); 
	float f90 = clamp(dot(f0, vec3(16.5)), m, 1.0);

	vec3 F = f0 + (f90 - f0) * pow(1.0 - cHdotL, 5.0);

	return max(D * G * F * cNdotL, 0.0);
}

void fragment()
{
	ALBEDO = diffuse_color;
	ROUGHNESS = roughness;
	METALLIC = metallic;
	SPECULAR = metallic_specular;
}

void light()
{
	vec3 n = normalize( NORMAL );
	vec3 l = normalize( LIGHT );
	vec3 v = normalize( VIEW );

	vec3 h = normalize(v + l); // Halfway Vector.

	float NdotL = dot(n, l); // [-1.0, 1.0].
	float NdotV = dot(n, v); // [-1.0, 1.0].

	float HdotN = dot(h, n); // [-1.0, 1.0].
	float HdotL = dot(h, l); // [-1.0, 1.0].

	float cNdotL = max(NdotL, 0.0); // [0.0, 1.0].
	float cNdotV = max(NdotV, 0.0); // [0.0, 1.0].

	float cHdotN = max(HdotN, 0.0); // [0.0, 1.0].
	float cHdotL = max(HdotL, 0.0); // [0.0, 1.0].

	/* Diffuse Burley */ 
	float d = diffuse_burley(cNdotL, cNdotV, cHdotL, ROUGHNESS);

	/* Specular Schlick-GGX */
	vec3 s = specular_schlick_ggx(cNdotL, cNdotV, cHdotN, cHdotL, ALBEDO, ROUGHNESS, METALLIC, metallic_specular);

	DIFFUSE_LIGHT += LIGHT_COLOR * ATTENUATION * d;
	SPECULAR_LIGHT += LIGHT_COLOR * ATTENUATION * s;
}
```

This produces the following results:

<img width="1920" height="1080" alt="Image" src="https://github.com/user-attachments/assets/4dacae06-382c-4bfb-a5dc-8901bb59ddbf" />

<img width="1920" height="1080" alt="Image" src="https://github.com/user-attachments/assets/8a45d60b-2d68-4eae-8f9b-066160eef5f6" />

This is my implementation based on the original implementation described by Burley here: [Physically Based Shading at Disney](https://media.disneyanimation.com/uploads/production/publication_asset/48/asset/s2012_pbs_disney_brdf_notes_v3.pdf)

```glsl
shader_type spatial;

uniform vec3 _DiffuseColor : source_color = vec3(1.0);
uniform float _Roughness : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Metallic : hint_range(0.0, 1.0, 1e-3) = 0.0;
uniform float _MetallicSpecular : hint_range(0.0, 1.0, 1e-3) = 0.5;

uniform float _Rho : hint_range(0.0, 1.0, 1e-3) = 1.0;

void fragment() {
	ALBEDO = _DiffuseColor;
	ROUGHNESS = _Roughness;
	METALLIC = _Metallic;
	SPECULAR = _MetallicSpecular;
}

void light() {
	vec3 n = normalize(NORMAL);
	vec3 l = normalize(LIGHT);
	vec3 v = normalize(VIEW);

	vec3 h = normalize(v + l);

	float alpha = ROUGHNESS * ROUGHNESS;
	float alpha_2 = alpha * alpha;

	float NdotL = dot(n, l); // cos(theta_l) == cos(theta_i).
	float NdotV = dot(n, v); // cos(theta_v) == cos(theta_r).
	float NdotH = dot(n, h); // cos(theta_h).

	float HdotL = dot(h, v); // cos(theta_d).

	float cNdotL = max(NdotL, 0.0);
	float cNdotV = max(NdotV, 0.0);
	float cNdotH = max(NdotH, 0.0);

	float cHdotL = max(HdotL, 0.0);

	/* Burley */
	float FD_l = pow(clamp(1.0 - NdotL, 0.0, 1.0), 5.0);
	float FD_v = pow(clamp(1.0 - NdotV, 0.0, 1.0), 5.0);

	float FD90 = 0.5 + 2.0 * ROUGHNESS * HdotL * HdotL;

	float f_d = (_Rho / PI) * mix(1.0, FD90, FD_l) * mix(1.0, FD90, FD_v) * cNdotL;

	/* Trowbridge-Reitz-GGX */

	/* Normal Distribution Function (GGX) */
	float D = alpha_2 / ( PI * pow(1.0 + (alpha_2 - 1.0) * NdotH * NdotH, 2.0) );

	/* Geometric Function (Implicit) */
	//float G = 0.5 / mix(2.0 * NdotL * NdotV, NdotL + NdotV, alpha);

	/* Geometric Function (Smith-GGX) */
	float GL = 1.0 / (NdotL + sqrt(alpha_2 + (NdotL * NdotL) - alpha_2 * (NdotL * NdotL)));
	float GV = 1.0 / (NdotV + sqrt(alpha_2 + (NdotV * NdotV) - alpha_2 * (NdotV * NdotV)));

	float G = GL * GV;

	/* Fresnel Function (Schlick’s Approximation) */
	vec3 f0 = mix(vec3(_MetallicSpecular * 0.08), ALBEDO, vec3(METALLIC));

	vec3 F = f0 + (1.0 - f0) * pow(1.0 - HdotL, 5.0);

	vec3 f_s = min(max(D * G * F * cNdotL, 0.0), 1.0);

	DIFFUSE_LIGHT += LIGHT_COLOR * ATTENUATION * f_d;
	SPECULAR_LIGHT += LIGHT_COLOR * ATTENUATION * f_s;
}
```

<br>

Furthermore, I propose using the Smith-GGX geometric function instead of the implicit version. This produces the following results:

