When rendering a slice image within Godot and comparing it to the rendered result, I encountered this problem again; they didn't match. Godot is much brighter. Normalizing the incoming light to 1.0 produces the correct result:

<img width="1920" height="1080" alt="Image" src="https://github.com/user-attachments/assets/ef8096e0-862f-447e-b9d3-b1c08740260c" />

Multiplying by 1.5 energy units such as @betalars yields the following result:

<img width="1920" height="1080" alt="Image" src="https://github.com/user-attachments/assets/0b47ad10-8608-4bb5-b2df-4114c9d58740" />

The original Burley violates the law of conservation of energy to some extent, but it is likely that the cause of the "glow" is LIGHT_COLOR.

GDSL BurleyGGX:
``` glsl
shader_type spatial;
render_mode skip_vertex_transform;

#define TRANSLATION_MATRIX(t) mat4(\
	vec4(1, 0, 0, t.x),\
	vec4(0, 1, 0, t.y),\
	vec4(0, 0, 1, t.z),\
	vec4(0, 0, 0, 1)\
	);

#define ROTATION_MATRIX_X(a) mat4(\
	vec4(1, 0, 0, 0),\
	vec4(0, cos(a), -sin(a), 0),\
	vec4(0, sin(a),  cos(a), 0),\
	vec4(0, 0, 0, 1)\
	);
#define ROTATION_MATRIX_Y(b) mat4(\
	vec4( cos(b), 0, sin(b), 0),\
	vec4(0, 1, 0, 0),\
	vec4(-sin(b), 0, cos(b), 0),\
	vec4(0, 0, 0, 1)\
	);
#define ROTATION_MATRIX_Z(c) mat4(\
	vec4(cos(c), -sin(c), 0, 0),\
	vec4(sin(c),  cos(c), 0, 0),\
	vec4(0, 0, 1, 0),\
	vec4(0, 0, 0, 1)\
	);

#define ESCALATION_MATRIX(s) mat4(\
	vec4(s.x, 0, 0, 0),\
	vec4(0, s.y, 0, 0),\
	vec4(0, 0, s.z, 0),\
	vec4(0, 0, 0, 1)\
	);

group_uniforms _Transform;
uniform vec3 _Position = vec3(0.0);
uniform vec3 _Rotation = vec3(0.0);
uniform vec3 _Scale = vec3(1.0);

group_uniforms _BurleyGGX;
uniform vec3 _DiffuseColor : source_color = vec3(1.0);
uniform float _Rho : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Roughness : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Metallic : hint_range(0.0, 1.0, 1e-3) = 0.0;
uniform float _MetallicSpecular : hint_range(0.0, 1.0, 1e-3) = 0.5;

varying vec4 _vertex_os;
varying vec4 _normal_os;
varying vec4 _binormal_os;
varying vec4 _tangent_os;

mat4 ROTATION_MATRIX(vec3 euler_angles_rad)
{
	mat4 x = ROTATION_MATRIX_X(euler_angles_rad.x)
	mat4 y = ROTATION_MATRIX_Y(euler_angles_rad.y)
	mat4 z = ROTATION_MATRIX_Z(euler_angles_rad.z)
	return y * x * z;
}

vec3 normalizeLinf(vec3 x)
{
	float norm = max(max(abs(x.x), abs(x.y)), abs(x.z));
	return x / norm;
}

void vertex()
{
	/* Rotation */
	vec3 angle_rad = radians(_Rotation);

	/* Vertex */
	_vertex_os = vec4(VERTEX, 1.0);

	_vertex_os *= ESCALATION_MATRIX(_Scale)

	_vertex_os *= ROTATION_MATRIX(angle_rad);

	vec4 vertex_ws = MODEL_MATRIX * _vertex_os;

	vertex_ws *= TRANSLATION_MATRIX(_Position)

	vec4 vertex_vs = VIEW_MATRIX * vertex_ws;

	VERTEX = vertex_vs.xyz;

	/* Normal */
	_normal_os = vec4(NORMAL, 0.0);

	_normal_os *= ROTATION_MATRIX(angle_rad);

	vec4 normal_ws = MODEL_MATRIX * _normal_os;

	vec4 normal_vs = VIEW_MATRIX * normal_ws;

	NORMAL = normalize(normal_vs.xyz);

	/* Binormal */
	_binormal_os = vec4(BINORMAL, 0.0);

	_binormal_os *= ROTATION_MATRIX(angle_rad);

	vec4 binormal_ws = MODEL_MATRIX * _binormal_os;

	vec4 binormal_vs = VIEW_MATRIX * binormal_ws;

	BINORMAL = normalize(binormal_vs.xyz);

	/* Tangent */
	_tangent_os = vec4(TANGENT, 0.0);

	_tangent_os *= ROTATION_MATRIX(angle_rad);

	vec4 tangent_ws = MODEL_MATRIX * _tangent_os;

	vec4 tangent_vs = VIEW_MATRIX * tangent_ws;

	TANGENT = normalize(tangent_vs.xyz);

	/* Projection */
	vec4 vertex_proj = PROJECTION_MATRIX * vertex_vs;

	POSITION = vertex_proj;
}

void fragment() {
	ALBEDO = _DiffuseColor;
	ROUGHNESS = _Roughness;
	METALLIC = _Metallic;
	SPECULAR = _MetallicSpecular;
}

void light() {
	vec3 n = normalize(NORMAL);
	vec3 l = normalize(LIGHT);
	vec3 v = normalize(VIEW);

	vec3 h = normalize(v + l);

	float alpha = ROUGHNESS * ROUGHNESS;
	float alpha_2 = alpha * alpha;

	float NdotL = dot(n, l); // cos(theta_l) == cos(theta_i).
	float NdotV = dot(n, v); // cos(theta_v) == cos(theta_r).
	float NdotH = dot(n, h); // cos(theta_h).

	float HdotL = dot(h, v); // cos(theta_d).

	float cNdotL = max(NdotL, 0.0);
	float cNdotV = max(NdotV, 0.0);
	float cNdotH = max(NdotH, 0.0);

	float cHdotL = max(HdotL, 0.0);

	/* Burley */
	float FD_l = pow(clamp(1.0 - NdotL, 0.0, 1.0), 5.0);
	float FD_v = pow(clamp(1.0 - NdotV, 0.0, 1.0), 5.0);

	float FD90 = 0.5 + 2.0 * ROUGHNESS * HdotL * HdotL;

	float f_d = (_Rho / PI) * mix(1.0, FD90, FD_l) * mix(1.0, FD90, FD_v) * cNdotL;

	/* Trowbridge-Reitz-GGX */

	/* Normal Distribution Function (GGX) */
	float D = alpha_2 / ( PI * pow(1.0 + (alpha_2 - 1.0) * NdotH * NdotH, 2.0) );

	/* Geometric Function (Implicit) */
	//float G = 0.5 / mix(2.0 * NdotL * NdotV, NdotL + NdotV, alpha);

	/* Geometric Function (Smith-GGX) */
	float GL = 1.0 / (NdotL + sqrt(alpha_2 + (NdotL * NdotL) - alpha_2 * (NdotL * NdotL)));
	float GV = 1.0 / (NdotV + sqrt(alpha_2 + (NdotV * NdotV) - alpha_2 * (NdotV * NdotV)));

	float G = GL * GV;

	/* Fresnel Function (Schlick’s Approximation) */
	vec3 f0 = mix(vec3(_MetallicSpecular * 0.08), ALBEDO, vec3(METALLIC));

	vec3 F = f0 + (1.0 - f0) * pow(1.0 - HdotL, 5.0);

	vec3 f_s = min(max(D * G * F * cNdotL, 0.0), 1.0);

	DIFFUSE_LIGHT += normalizeLinf(LIGHT_COLOR) * ATTENUATION * f_d;
	SPECULAR_LIGHT += normalizeLinf(LIGHT_COLOR) * ATTENUATION * f_s;
}
```

GDSL BRDF BurleyGGX shader include:
``` glsl
group_uniforms _BurleyGGX;
uniform vec3 _DiffuseColor : source_color = vec3(1.0);
uniform float _Rho : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Roughness : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Metallic : hint_range(0.0, 1.0, 1e-3) = 0.0;
uniform float _MetallicSpecular : hint_range(0.0, 1.0, 1e-3) = 0.5;

vec3 to_linear(vec3 srgb)
{
	vec3 a = pow((srgb + 0.055) / 1.055, vec3(2.4));
	vec3 b = srgb / 12.92;
	bvec3 c = lessThan(srgb, vec3(0.04045));
	return mix(a, b, c);
}

vec3 BRDF(
	in vec3 n,
	in vec3 l,
	in vec3 v,
	in vec3 x,
	in vec3 y
)
{
	vec3 rho = to_linear(_DiffuseColor);

	vec3 h = normalize(v + l);

	float alpha = _Roughness * _Roughness;
	float alpha_2 = alpha * alpha;

	float NdotL = dot(n, l); // cos(theta_l) == cos(theta_i).
	float NdotV = dot(n, v); // cos(theta_v) == cos(theta_r).
	float NdotH = dot(n, h); // cos(theta_h).

	float HdotL = dot(h, l); // cos(theta_d).

	/* Burley */
	float FD_l = pow(clamp(1.0 - NdotL, 0.0, 1.0), 5.0);
	float FD_v = pow(clamp(1.0 - NdotV, 0.0, 1.0), 5.0);

	float FD90 = 0.5 + 2.0 * _Roughness * HdotL * HdotL;

	vec3 f_d = (_Rho / PI) * mix(1.0, FD90, FD_l) * mix(1.0, FD90, FD_v) * rho * (1.0 - _Metallic);

	/* Trowbridge-Reitz-GGX */

	/* Normal Distribution Function (GGX) */
	float D = alpha_2 / ( PI * pow(1.0 + (alpha_2 - 1.0) * NdotH * NdotH, 2.0) );

	/* Geometric Function (Implicit) */
	//float G = 0.5 / mix(2.0 * NdotL * NdotV, NdotL + NdotV, alpha);

	/* Geometric Function (Smith-GGX) */
	float GL = 1.0 / (NdotL + sqrt(alpha_2 + (NdotL * NdotL) - alpha_2 * (NdotL * NdotL)));
	float GV = 1.0 / (NdotV + sqrt(alpha_2 + (NdotV * NdotV) - alpha_2 * (NdotV * NdotV)));

	float G = GL * GV;

	/* Fresnel Function (Schlick’s Approximation) */
	vec3 f0 = mix(vec3(_MetallicSpecular * 0.08), rho, vec3(_Metallic));

	vec3 F = f0 + (1.0 - f0) * pow(1.0 - HdotL, 5.0);

	vec3 f_s = min(max(D * G * F, 0.0), 1.0);

	return vec3( f_d + f_s );
}
```

GDSL SliceImage:
``` glsl
shader_type canvas_item;

uniform float _PhiH : hint_range(0.0, 180.0, 1e-3) = 0.0; // incident phi.
uniform float _PhiD : hint_range(0.0, 180.0, 1e-3) = 90.0;

uniform float _Brightness : hint_range(0.0, 1.0, 1e-3) = 1.0;
uniform float _Exposure : hint_range(-6.0, 6.0, 1e-3) = 0.0;
uniform float _Gamma : hint_range(1.0, 5.0, 1e-3) = 2.2;

#include "./brdf/BurleyGGX.gdshaderinc"

group_uniforms UV;
uniform vec2 _Tiling = vec2(1.0);
uniform vec2 _Offset = vec2(0.0);

vec2 tiling_and_offset(
	in vec2 st,
	in vec2 tiling,
	in vec2 offset
	)
{
	return vec2(st.x * tiling.x + offset.x, st.y * tiling.y + offset.y);
}

vec3 rotate_vector(
	in vec3 vector,
	in vec3 axis,
	in float angle
)
{
	axis = normalize(axis);

	vec3 n = axis * dot(axis, vector);

	return n + cos(angle) * (vector - n) + sin(angle) * cross(axis, vector);
}

void fragment() {

	vec2 st = tiling_and_offset(UV, _Tiling, _Offset);

	// Orthonormal vectors.
	vec3 normal = vec3(0,0,1); // n.
	vec3 tangent = vec3(1,0,0); // x.
	vec3 bitangent = vec3(0,1,0); // y.

	float phi_h = _PhiH * (PI / 180.0);

	float theta_h = st.x * (PI * 0.5);

	vec3 h = vec3(sin(theta_h) * cos(phi_h), sin(theta_h) * sin(phi_h), cos(theta_h));

	float phi_d = _PhiD * (PI / 180.0);

	float theta_d = (1.0 - st.y) * (PI * 0.5);

	float sin_theta_d = sin(theta_d);
	float cos_theta_d = cos(theta_d);

	float sin_phi_d = sin(phi_d);
	float cos_phi_d = cos(phi_d);

	vec3 d = vec3(sin_theta_d * cos_phi_d, sin_theta_d * sin_phi_d, cos_theta_d);

	vec3 light = rotate_vector(rotate_vector(d, bitangent, theta_h), normal, phi_h);

	vec3 view = reflect(-light, h);

	vec3 b = BRDF(normal, light, view, tangent, bitangent);

	b *= _Brightness;

	b *= pow(2.0, _Exposure);

	b = pow( b, vec3( 1.0 / _Gamma ) );

	COLOR = vec4(clamp(b, 0.0, 1.0), 1.0);
}
```

P.S. When roughness is zero, the specular reflection disappears due to the equation itself :p
